package app.flow.player;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.DocumentsContract;import org.json.*;import java.util.*;
final class LocalLibrary {
 static String name(Context c,Uri uri){try(Cursor row=c.getContentResolver().query(uri,new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(row!=null&&row.moveToFirst())return row.getString(0);}catch(Exception ignored){}String raw=uri.getLastPathSegment();return raw==null?"Selected file":raw.substring(raw.lastIndexOf(':')+1);}
 static JSONObject list(Context c,String address)throws Exception{Uri tree=Uri.parse(address);if(!"content".equals(tree.getScheme()))throw new IllegalArgumentException();String id=DocumentsContract.isDocumentUri(c,tree)?DocumentsContract.getDocumentId(tree):DocumentsContract.getTreeDocumentId(tree);Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,id);ArrayList<JSONObject> items=new ArrayList<>();String[] cols={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE};try(Cursor rows=c.getContentResolver().query(children,cols,null,null,null)){if(rows!=null)while(rows.moveToNext()){String documentId=rows.getString(0),title=rows.getString(1),mime=rows.getString(2);if(mime==null)mime="application/octet-stream";boolean dir=DocumentsContract.Document.MIME_TYPE_DIR.equals(mime);if(!dir&&!mime.startsWith("video/")&&!mime.startsWith("audio/")&&!title.toLowerCase(Locale.ROOT).matches(".*\\.(mp4|mkv|webm|avi|mov|ts|m2ts|mpg|mpeg|m4v|wmv|flv|mp3|m4a|aac|wav|ogg|opus|flac|ac3|dts)$"))continue;Uri file=DocumentsContract.buildDocumentUriUsingTree(tree,documentId);items.add(new JSONObject().put("name",title).put("url",file.toString()).put("directory",dir).put("local",true).put("audio",mime.startsWith("audio/")).put("size",rows.getLong(3)));}}items.sort((a,b)->{int folders=Boolean.compare(b.optBoolean("directory"),a.optBoolean("directory"));return folders!=0?folders:a.optString("name").compareToIgnoreCase(b.optString("name"));});JSONArray files=new JSONArray();for(JSONObject item:items)files.put(item);return new JSONObject().put("url",address).put("name",name(c,DocumentsContract.buildDocumentUriUsingTree(tree,id))).put("files",files);}
 static JSONArray roots(Context c){JSONArray result=new JSONArray();for(UriPermission permission:c.getContentResolver().getPersistedUriPermissions()){Uri uri=permission.getUri();if(!permission.isReadPermission()||!DocumentsContract.isTreeUri(uri))continue;try{String id=DocumentsContract.getTreeDocumentId(uri);result.put(new JSONObject().put("url",uri.toString()).put("name",name(c,DocumentsContract.buildDocumentUriUsingTree(uri,id))).put("directory",true).put("local",true));}catch(Exception ignored){}}return result;}
}
